    String summary(Course c){return "周"+"一二三四五六日".charAt(c.day-1)+"  第 "+c.start+"–"+c.end+" 节"+(c.room.isEmpty()?"":"  ·  "+c.room);}
    void showCourse(Course c){new AlertDialog.Builder(this).setTitle(c.name).setMessage(summary(c)+"\n"+Course.weeksText(c.weeks)+" 周\n"+(c.teacher.isEmpty()?"":"教师："+c.teacher+"\n")+(c.note.isEmpty()?"":"\n"+c.note)).setPositiveButton("编辑",(d,w)->editCourse(c,true)).setNegativeButton("关闭",null).setNeutralButton("删除",(d,w)->new AlertDialog.Builder(this).setTitle("删除这条上课安排？").setMessage(c.name+"\n其他课程和其他安排会保留。").setPositiveButton("删除",(dd,ww)->mutate(()->store.courses.removeIf(x->x.id.equals(c.id)))).setNegativeButton("取消",null).show()).show();}
    void mutate(Runnable action){List<Course> before=new ArrayList<>(store.courses);try{if(store.loadFailed)throw new IllegalStateException("请先从备份恢复，原始数据尚未修复");action.run();store.save();render();}catch(Exception e){store.courses.clear();store.courses.addAll(before);toast(e.getMessage());}}
    void editCourse(Course c,boolean existing){editor(c,updated->{boolean conflict=store.courses.stream().anyMatch(x->!x.id.equals(updated.id)&&x.clashes(updated));Runnable save=()->mutate(()->{if(existing)store.courses.removeIf(x->x.id.equals(updated.id));store.courses.add(updated);});if(conflict)new AlertDialog.Builder(this).setTitle("有课程时间重叠").setMessage("部分周次有其他课程在同一天同一节。仍要保存这条安排吗？").setPositiveButton("仍然保存",(d,w)->save.run()).setNegativeButton("取消",null).show();else save.run();});}
