        fields.addView(Ui.text(this,"星期",12,Ui.MUTED,false));Spinner days=new Spinner(this);days.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"周一","周二","周三","周四","周五","周六","周日"}));days.setSelection(c.day-1);fields.addView(days,new LinearLayout.LayoutParams(-1,Ui.dp(this,48)));Ui.gap(this,fields,10);
