        EditText name=Ui.input(this,term,"学期名称",store.termName(),InputType.TYPE_CLASS_TEXT),monday=Ui.input(this,term,"第 1 周的周一（点击选择）",store.termSet()?store.monday().toString():"",InputType.TYPE_NULL);monday.setFocusable(false);monday.setOnClickListener(v->{LocalDate date=store.monday();new DatePickerDialog(this,(picker,y,m,d)->monday.setText(LocalDate.of(y,m+1,d).toString()),date.getYear(),date.getMonthValue()-1,date.getDayOfMonth()).show();});
